from flask import Flask, request, Response
import subprocess

app = Flask(__name__)

@app.route('/profile')
def profile():
    name = request.args.get('name')
    description = request.args.get('description')
    interests = request.args.get('interests').replace(';', '').split()

    # Disabling shell=True param mitigates command injection by preventing the use of shell metacharacters like |, <, >, etc.
    process = subprocess.run(['echo', f"Name: {name}\nDescription: {description}\nInterests: {interests}"],
                             shell=False)

    if process.returncode:
        return Response("Error processing profile request", status=500)

    return Response("Thank you for updating your profile info!")

if __name__ == '__main__':
    app.run()

