from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/upload", methods=["POST"])
def upload_profile():
    # Retrieve "profile" and "server" parameters from POST request
    profile = request.form.get("profile")
    server = request.form.get("server")

    # Default to safe server URLs if not specified by user
    if not server:
        server = "images.production.com"

    return jsonify({"image": f"https://{server}/profile/{profile}.png"})

if __name__ == "__main__":
    app.run()

