@app.route("/guestlist")
def guestlist():
    new_guest = request.args.get('new_guest').encode('utf-8')
    message = '<h1>Welcome to the dinner party!</h1>'
    if new_guest:
        if not new_guest.isalpha():
            name = escape(new_guest)
            message += "<p>Hi {}! We'd love to have you.</p>".format(name)
            # Attacker can inject malicious scripts via new_guest parameter
            message += "Note: new guests: {}".format(escape(new_guest))
        else:
            # Directly uses untrusted user input; unsanitized string allows XSS
            message += "Note: new guests: {}".format(new_guest)
    return message

