from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/data')
def get_data():
    user = request.args.get('user')

    if not user:
        return jsonify({'error': 'No user parameter provided'})

    # Vulnerable: user input is inserted directly into HTML without escaping
    data = "<h3>Thank you for registering, {}!</h3>".format(user)

    # Importantly: this allows injection of malicious code that will execute in the browser
    return jsonify({'data': data})

if __name__ == '__main__':
    app.run()
